head.script:
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
scwin.fn_GetPar, scwin.fn_SetPar, scwin.strCdSch, scwin.queryId, scwin.gubun;
scwin.fr_SecuGrpId; // 증권그룹ID

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        window.document.body.scroll = "no";
        let arrPar = new Array();
        /***************************************
        opener에  fn_GetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 업종조회후  최초 지정 코드값이 없는 상태
        opener에  fn_SetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 선택한 코드값과 코드명칭을 지정하지 않는다.
         ***************************************/
        const parentWin = $c.frame.path("../");
        scwin.fn_GetPar = parentWin.scwin.fn_GetPar;
        scwin.fn_SetPar = parentWin.scwin.fn_SetPar;
        if (scwin.fn_GetPar !== undefined) {
            scwin.fn_GetPar(arrPar);
            scwin.queryId = (arrPar.length >= 1 ? arrPar[0] : "");
            scwin.gubun = (arrPar.length >= 2 ? arrPar[1] : "");
        }
        scwin.setColumnName();
        txb_Search.focus();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70017_6.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name txb_Search_onkeydown
 * @description txb_Search 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_Search_onkeydown = async function() {
    try {
        if (event.keyCode === 13) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70017_6.txb_Search_onkeydown" });
    }
};

/**
 * @method
 * @name dts_OnLoadError
 * @description dts 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_OnLoadError = async function() {
    try {
        await $c.win.alert(dts);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70017_6.dts_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_OnLoadCompleted
 * @description dts 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts.errorMsg) {
            await $c.win.alert(dts.errorMsg);
        } else {
            txb_TotCnt.setValue("총 " + rowcount + " 건");

            // 초기1회 초기값으로 설정된 회사코드를 검색한다.
            if (scwin.strCdSch !== "") {
                for (let i = 1; i <= dts.getRowCount(); i++) {
                    if (scwin.strCdSch === dts.getCellData(i, 1)) {
                        dts.setRowPosition(i, 0);
                        break;
                    }
                }
                scwin.strCdSch = "";
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70017_6.dts_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_OnDblClick
 * @description grd 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_OnDblClick = async function(row, colid) {
    try {
        let arrPar = new Array();
        if (scwin.fn_SetPar !== undefined) {
            arrPar[0] = {
                ISUR_CD: dts.getCellData(dts.getRowPosition(), "ISUR_CD"),
                ISUR_NM: dts.getCellData(dts.getRowPosition(), "ISUR_NM"),
                DBCLICKYN: "Y"
            };
            scwin.fn_SetPar(arrPar);
        }
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70017_6.grd_OnDblClick" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70017_6.img_Search_onclick" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70017_6.img_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_dts",
        action : "/listingCommon.do",
        ref : "",
        target : "dts=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setColumnName
 * @description set Column Name 처리
 * @returns {void}
 * @hidden N
 */
scwin.setColumnName = function() {
    if (scwin.gubun === "B") {
        $c.cm.setColumnProp(grd, 'ISUR_CD', 'Name', "신탁기관코드");
        $c.cm.setColumnProp(grd, 'ISUR_NM', 'Name', "신탁기관명");
        label_1.setValue("신탁기관명");
    }
};
